// Layout primitive (Category B) — arrangement only, owns no look.
// Carve-out 5 (component-contract.md §6): references Sys layout scales directly,
// no Cmp token layer. 2D grid — fixed column count, or auto-fit via minItemWidth.
// Responsive: columns/gap/align accept `T | { small, medium, large }` (block-contract.md § Responsive).
import type { CSSProperties, ElementType, HTMLAttributes, Ref } from "react";
import { responsiveVars, type Responsive } from "./responsive";
import "./Grid.css";

type Gap =
  | "none"
  | "2x-small"
  | "x-small"
  | "small"
  | "medium"
  | "large"
  | "x-large"
  | "2x-large";
type Align = "start" | "center" | "end" | "stretch";

const gapValue = (v: Gap) => (v === "none" ? "0" : `var(--sd-space-${v})`);
const template = (n: number) => `repeat(${n}, minmax(0, 1fr))`;

export interface GridProps extends Omit<HTMLAttributes<HTMLElement>, "className"> {
  /** Fixed number of equal columns. Ignored when `minItemWidth` is set. */
  columns?: Responsive<number>;
  /** Auto-fit columns at least this wide (e.g. "16rem"); overrides `columns`. */
  minItemWidth?: string;
  /**
   * With `minItemWidth`: `fit` stretches the cells across the row when there are few of them; `fill`
   * keeps empty tracks, so a cell is as wide with two items as with ten.
   *
   * @default "fit"
   */
  minItemMode?: "fit" | "fill";
  /**
   * One row of items, each this wide, running past the inline edge: the track of a peek scroller,
   * wrapped in a `ScrollArea` that owns the scrolling (e.g. "17rem"). Overrides `columns` and
   * `minItemWidth`. Every item keeps the width however many there are, so the last one shows cut
   * off at the edge as the cue that the row scrolls.
   */
  itemWidth?: string;
  /**
   * Space between cells, from the Sys space scale. A responsive value's default is the value at
   * every rung.
   *
   * @default "medium"
   */
  gap?: Responsive<Gap>;
  /** Cross-axis alignment of cells (align-items). */
  align?: Responsive<Align>;
  /** Render as a different element. */
  as?: ElementType;
  className?: string;
  style?: CSSProperties;
  ref?: Ref<HTMLElement>;
}

export function Grid({
  columns = 1,
  minItemWidth,
  minItemMode = "fit",
  itemWidth,
  gap = "medium",
  align,
  as: Component = "div",
  className,
  style,
  ...props
}: GridProps) {
  const templateVars: CSSProperties = itemWidth
    ? ({ "--sd-layout-grid-template-small": "none", "--sd-layout-grid-item-width": itemWidth } as CSSProperties)
    : minItemWidth
    ? ({
        "--sd-layout-grid-template-small": `repeat(auto-${minItemMode}, minmax(min(${minItemWidth}, 100%), 1fr))`,
      } as CSSProperties)
    : responsiveVars("grid-template", columns, template);
  return (
    <Component
      {...props}
      className={className ? `sd-grid ${className}` : "sd-grid"}
      data-flow={itemWidth ? "row" : undefined}
      style={{
        ...templateVars,
        ...responsiveVars("gap", gap, gapValue),
        ...responsiveVars("align", align, (v) => v),
        ...style,
      }}
    />
  );
}

/* Grid.css — .sd-grid
   Layout primitive: arrangement only. Carve-out 5 — references Sys space scale
   directly. The column template + gap/align arrive as --sd-layout-* local custom
   properties (set inline); applied mobile-first with a base → md (768px) cascade.
   --sd-layout-* are local intermediates, not tokens. No descendant combinators. */
.sd-grid {
  /* Block inheritance of the inline per-instance --sd-layout-* vars (see Stack.css). */
  --sd-layout-grid-template-small: initial;
  --sd-layout-grid-template-medium: initial;
  --sd-layout-grid-template-large: initial;
  --sd-layout-gap-small: initial;
  --sd-layout-gap-medium: initial;
  --sd-layout-gap-large: initial;
  --sd-layout-align-small: initial;
  --sd-layout-align-medium: initial;
  --sd-layout-align-large: initial;
  --sd-layout-grid-item-width: initial;
  display: grid;
  grid-template-columns: var(--sd-layout-grid-template-small, repeat(1, minmax(0, 1fr)));
  gap: var(--sd-layout-gap-small, var(--sd-space-medium));
  align-items: var(--sd-layout-align-small, stretch);
}

@media (min-width: 768px) {
  .sd-grid {
    grid-template-columns: var(
      --sd-layout-grid-template-medium,
      var(--sd-layout-grid-template-small, repeat(1, minmax(0, 1fr)))
    );
    gap: var(--sd-layout-gap-medium, var(--sd-layout-gap-small, var(--sd-space-medium)));
    align-items: var(--sd-layout-align-medium, var(--sd-layout-align-small, stretch));
  }
}

@media (min-width: 1024px) {
  .sd-grid {
    grid-template-columns: var(
      --sd-layout-grid-template-large,
      var(--sd-layout-grid-template-medium, var(--sd-layout-grid-template-small, repeat(1, minmax(0, 1fr))))
    );
    gap: var(--sd-layout-gap-large, var(--sd-layout-gap-medium, var(--sd-layout-gap-small, var(--sd-space-medium))));
    align-items: var(--sd-layout-align-large, var(--sd-layout-align-medium, var(--sd-layout-align-small, stretch)));
  }
}

/* `itemWidth`: one row of fixed-width items that runs past the edge (a peek scroller's track). The
   columns are implicit, one per item, so the row is as long as its content and its ScrollArea
   scrolls it. */
.sd-grid[data-flow="row"] {
  grid-auto-flow: column;
  grid-auto-columns: var(--sd-layout-grid-item-width);
}
